+// Import required stores
+import { createSettingsStore } from '../L2-002-settings-store/settingsStore.mjs';
+import { createTodoStore } from '../L2-003-todo-store/todoStore.mjs';
+
+// Create the desk tool
+export function createDeskTool(rootDir, { defaults = { theme: 'dark', compact: false } } = {}) {
+  // Create stores
+  const settingsStore = createSettingsStore({
+    filePath: `${rootDir}/settings.json`,
+    defaults
+  });
+
+  const todoStore = createTodoStore({
+    filePath: `${rootDir}/todos.json`
+  });
+
+  // Create the desk tool object
+  const deskTool = Object.freeze({
+    // Get settings
+    getSettings: () => settingsStore.getSettings(),
+
+    // Set setting
+    setSetting: (key, value) => {
+      const updatedSettings = { ...settingsStore.getSettings(), [key]: value };
+      return settingsStore.setSettings(updatedSettings);
+    },
+
+    // List todos
+    listTodos: () => todoStore.listTodos(),
+
+    // Add todo
+    addTodo: (todo) => todoStore.addTodo(todo),
+
+    // Update todo
+    updateTodo: (id, updates) => todoStore.updateTodo(id, updates),
+
+    // Remove todo
+    removeTodo: (id) => todoStore.removeTodo(id),
+
+    // Export JSON
+    exportJson: () => {
+      const settings = settingsStore.getSettings();
+      const todos = todoStore.listTodos();
+      return JSON.stringify({
+        settings,
+        todos
+      });
+    },
+
+    // Import JSON
+    importJson: (json) => {
+      try {
+        const { settings, todos } = JSON.parse(json);
+
+        // Validate settings
+        const validatedSettings = settingsStore.validateSettings(settings);
+
+        // Validate todos
+        const validatedTodos = todoStore.validateTodos(todos);
+
+        // Create a temporary directory for staging
+        const stagingDir = `${rootDir}/staging`;
+        const settingsFilePath = `${stagingDir}/settings.json`;
+        const todosFilePath = `${stagingDir}/todos.json`;
+
+        // Write validated settings and todos to staging files
+        writeFileSync(settingsFilePath, JSON.stringify(validatedSettings));
+        writeFileSync(todosFilePath, JSON.stringify(validatedTodos));
+
+        // Replace live files with staged files
+        const liveSettingsFilePath = `${rootDir}/settings.json`;
+        const liveTodosFilePath = `${rootDir}/todos.json`;
+
+        // Backup live files
+        const liveSettingsBackupFilePath = `${liveSettingsFilePath}.bak`;
+        const liveTodosBackupFilePath = `${liveTodosFilePath}.bak`;
+
+        // Move live files to backup
+        renameSync(liveSettingsFilePath, liveSettingsBackupFilePath);
+        renameSync(liveTodosFilePath, liveTodosBackupFilePath);
+
+        // Replace live files with staged files
+        renameSync(settingsFilePath, liveSettingsFilePath);
+        renameSync(todosFilePath, liveTodosFilePath);
+
+        // Return success
+        return true;
+      } catch (error) {
+        // Rollback live files
+        const liveSettingsFilePath = `${rootDir}/settings.json`;
+        const liveTodosFilePath = `${rootDir}/todos.json`;
+
+        // Restore live files from backup
+        const liveSettingsBackupFilePath = `${liveSettingsFilePath}.bak`;
+        const liveTodosBackupFilePath = `${liveTodosFilePath}.bak`;
+
+        if (existsSync(liveSettingsBackupFilePath)) {
+          renameSync(liveSettingsBackupFilePath, liveSettingsFilePath);
+        }
+
+        if (existsSync(liveTodosBackupFilePath)) {
+          renameSync(liveTodosBackupFilePath, liveTodosFilePath);
+        }
+
+        // Reject invalid import
+        throw new Error('INVALID_IMPORT');
+      }
+    },
+
+    // Summary
+    summary: () => {
+      const settings = settingsStore.getSettings();
+      const todos = todoStore.listTodos();
+
+      const todoCount = todos.length;
+      const doneCount = todos.filter(todo => todo.completed).length;
+      const openCount = todos.length - doneCount;
+      const completionPct = todoCount === 0 ? 0 : Number(((doneCount / todoCount) * 100).toFixed(2));
+
+      return {
+        todoCount,
+        doneCount,
+        openCount,
+        completionPct
+      };
+    }
+  });
+
+  return deskTool;
+}

